actions.script:
activeOrgId = null
if (ec.user.isInGroup('ADMIN')) {
    def preference = ec.user.getPreference('ACTIVE_ORGANIZATION')
    activeOrgId = preference && preference != '_NA_' ? preference : null
    return
}
// Clear stale derived scope even when this account has no party or resolution fails.
ec.user.context.activeOrgId = null
ec.user.context.userOrgIds = []
ec.user.context.filterOrgIds = []
def callerPartyId = ec.user.userAccount?.partyId
if (!callerPartyId) return
// Only the authoritative relationship lookup bypasses entity filters. Shop
// operations keep their normal authorization. Mantle also clears invalid preferences.
def orgInfo = ec.service.sync().name('mantle.party.PartyServices.get#PartyOrganizationInfo')
        .parameters([partyId:callerPartyId]).disableAuthz().call()
if (ec.message.hasError()) return
def userOrgIds = orgInfo?.userOrgIds ?: []
def resolvedOrg = orgInfo?.activeOrgId
activeOrgId = resolvedOrg && resolvedOrg != '_NA_' && userOrgIds.contains(resolvedOrg) ? resolvedOrg : null
ec.user.context.activeOrgId = activeOrgId
ec.user.context.userOrgIds = userOrgIds
ec.user.context.filterOrgIds = activeOrgId ? [activeOrgId] : userOrgIds

safeRows = []
if (!scope.activeOrgId) return
def org = scope.activeOrgId
def facilities = ec.entity.find('mantle.facility.Facility').condition('ownerPartyId',org).list().collect {it.facilityId} as Set
def managers = ec.entity.find('mantle.party.Party').condition('ownerPartyId',org).list().collect {it.partyId} as Set
managers.addAll(ec.entity.find('zenith.erp.hr.Employee').condition('organizationPartyId',org).list().collect {it.partyId})
def managerByStore = ec.entity.find('zenith.erp.stores.Store').condition('organizationPartyId',org).list().collectEntries {[(it.storeId):it.managerPartyId]}
(rows ?: []).each { row ->
    if (row.organizationPartyId == org) {
        def copy = new LinkedHashMap(row)
        if (!facilities.contains(row.facilityId)) copy.facilityName = null
        if (!managers.contains(managerByStore[row.storeId])) {copy.managerFirstName = null; copy.managerLastName = null}
        safeRows.add(copy)
    }
}
